INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27101, 'Romans 11:25', 'Romans', 11, 25, '&nbsp;زما وروڼو او خوېندو، دا ځکه چې دلته يو پټ حقيقت دے او زۀ غواړم چې تاسو پرې پوهه شئ، د دې دپاره چې تاسو ځان بې‌ځايه عقلمند ونۀ ګڼئ، او هغه دا دے چې د بنى اِسرائيل يوه برخه به تر هغې سخته وى ترڅو چې غېر‌يهوديانو پوره پوره په دې کښې داخل نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27102, 'Romans 11:26', 'Romans', 11, 26, '&nbsp;او بيا ټول بنى اِسرائيل به خلاصون ومومى لکه څنګه چې صحيفو کښې ليکلے شوى دى چې، ”خلاصونکے به د صيون نه راپورته شى، هغه به د يعقوب د نسل نه بې‌دينى لرې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27103, 'Romans 11:27', 'Romans', 11, 27, '&nbsp;او دا زما د هغوئ سره يو لوظ دے چې کله د هغوئ ګناهونه لرې کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27104, 'Romans 11:28', 'Romans', 11, 28, '&nbsp;ډېر بنى اِسرائيل اوس هم د زيرى دشمنان دى. او دا ستاسو دپاره فائده ده. خو دوئ اوس هم خُدائ پاک ته د خپلو نيکونو اِبراهيم، اِسحاق او يعقوب په وجه ګران دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27105, 'Romans 11:29', 'Romans', 11, 29, '&nbsp;ځکه چې د خُدائ پاک نعمتونه او د هغۀ بلنه نۀ بدلېدونکې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27106, 'Romans 11:30', 'Romans', 11, 30, '&nbsp;لکه څنګه چې مخکښې تاسو غېر‌يهوديان د خُدائ پاک نافرمانه وئ، خو چې کله بنى اِسرائيلو د هغۀ نافرمانى وکړه نو د هغوئ په ځائ خُدائ پاک په تاسو رحم وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27107, 'Romans 11:31', 'Romans', 11, 31, '&nbsp;خو اوس هغوئ نافرمانه دى او د خُدائ پاک رحم په تاسو وشو نو چې دوئ هم ستاسو په وجه د خُدائ پاک په رحم کښې شريک شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27108, 'Romans 11:32', 'Romans', 11, 32, '&nbsp;ځکه خُدائ پاک ټول بنى آدم په نافرمانۍ کښې راګېر کړل نو چې هغه په ټولو باندې رحم وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27109, 'Romans 11:33', 'Romans', 11, 33, '&nbsp;واه، د خُدائ پاک دولت، عِلم او پوهه څومره بې‌پايانه ده، او د هغۀ اِنصاف څومره د عقل نه بهر دے او د هغۀ لارې څومره عجيبه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27110, 'Romans 11:34', 'Romans', 11, 34, '&nbsp;”د مالِک خُدائ په اراده څوک پوهېدے شى؟ يا څوک هغۀ ته مشوره ورکولے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27111, 'Romans 11:35', 'Romans', 11, 35, '&nbsp;يا چا هغۀ ته چرې څۀ ورکړى دى چې د هغۀ نه هم څۀ واخلى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27112, 'Romans 11:36', 'Romans', 11, 36, '&nbsp;ځکه چې دا ټول څيزونه د هغۀ د لاسه ملاويږى او د هغۀ په وسيله موجود دى او د هغۀ لويئ دپاره دى. د هغۀ ثنا دې تل تر تله وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27113, 'Romans 12:1', 'Romans', 12, 1, '&nbsp;نو په دې وجه، زما وروڼو او خوېندو، زۀ د خُدائ پاک د رحمتونو په وسيله تاسو ته منت کوم چې خپل ځانونه خُدائ پاک ته د داسې ژوندۍ قربانۍ دپاره وړاندې کړئ چې هغۀ ته مقدسه او قبوله وى، او هم دا ستاسو اصلى عبادت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27114, 'Romans 12:2', 'Romans', 12, 2, '&nbsp;خپل ځان د دې موجوده دُنيا په شان مۀ جوړَوئ، بلکې خُدائ پاک له دا موقع ورکړئ چې ستاسو زاړۀ خيالونه بدل کړى. بيا به تاسو په دې پوهه شئ چې د خُدائ پاک رضا څۀ ده او دا به وپېژنئ چې څۀ ښۀ او قبلېدونکى او کامِل دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27115, 'Romans 12:3', 'Romans', 12, 3, '&nbsp;د هغه فضل په مطابق کوم چې ما ته راکړے شوے دے، زۀ په تاسو کښې هر چا ته دا وايم چې تاسو خپل ځان د خپل حيثيت نه اوچت مۀ ګڼئ. څنګه چې خُدائ پاک هر چا ته يوه اندازه ايمان ورکړے دے، هغه دې خپل ځان د هغې په مطابق وګڼى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27116, 'Romans 12:4', 'Romans', 12, 4, '&nbsp;لکه څنګه چې زمونږ په بدن کښې ډېر اندامونه دى او د ټولو اندامونو کار يو شان نۀ دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27117, 'Romans 12:5', 'Romans', 12, 5, '&nbsp;نو مونږ چې ډېر يُو خو په عيسىٰ مسيح کښې يو بدن يُو، او د يو بل سره تړلى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27118, 'Romans 12:6', 'Romans', 12, 6, '&nbsp;مونږ ته د فضل په مطابق مختلف نعمتونه مِلاو شوى دى. کۀ تاسو ته د پېشګوئې نعمت مِلاو شوے وى نو د ايمان په مطابق پېشګوئې کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27119, 'Romans 12:7', 'Romans', 12, 7, '&nbsp;کۀ تاسو ته خِدمت درکړے شوے وى نو خِدمت کوئ، کۀ د تعليم نعمت درکړے شوے وى نو تعليم ورکوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27120, 'Romans 12:8', 'Romans', 12, 8, '&nbsp;او کۀ د ډاډګيرنې نعمت يې درکړے وى نو ډاډګيرنه ورکوئ، کۀ د سخاوت نعمت يې درکړے وى نو سخاوت کوئ او کۀ د مشرۍ نعمت يې درکړے وى نو په محنت يې کوئ، کۀ د رحم نعمت يې درکړے وى نو ښۀ په خوشحالۍ رحم کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27121, 'Romans 12:9', 'Romans', 12, 9, '&nbsp;مينه دې بې‌ريا وى. د بدۍ نه نفرت کوئ او د نېکۍ سره ځان ونغاړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27122, 'Romans 12:10', 'Romans', 12, 10, '&nbsp;لکه د وروڼو د يو بل سره مينه کوئ او په عزت کولو کښې د يو بل نه مخکښې کېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27123, 'Romans 12:11', 'Romans', 12, 11, '&nbsp;په کار کښې سستى مۀ کوئ، او د مالِک په خِدمت کښې روحانى جوش‌و‌جذبه قائمه ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27124, 'Romans 12:12', 'Romans', 12, 12, '&nbsp;په اُميد کښې خوشحاله، په مصيبت کښې صابر او په دُعا کښې مشغول اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27125, 'Romans 12:13', 'Romans', 12, 13, '&nbsp;د مقدسينو په حاجتونو کښې مدد کوئ او د مسافرانو د مېلمستيا خيال ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27126, 'Romans 12:14', 'Romans', 12, 14, '&nbsp;څوک چې تاسو زوروى د هغوئ خير غواړئ، برکت يې غواړئ او ښيرى ورته مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27127, 'Romans 12:15', 'Romans', 12, 15, '&nbsp;څوک چې خوشحاله وى ورسره خوشحالى کوئ، څوک چې ژاړى ورسره ژړا کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27128, 'Romans 12:16', 'Romans', 12, 16, '&nbsp;په خپلو کښې په يو زړۀ اوسئ، لوئ لوئ خيالونه مۀ کوئ بلکې د بې‌وسو ملګرتيا کوئ او خپل ځان هوښيار مۀ ګڼئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27129, 'Romans 12:17', 'Romans', 12, 17, '&nbsp;د بدۍ په بدله کښې د چا سره بدى مۀ کوئ. هم هغه کارونه کوئ چې د هر چا په نظر کښې د عزت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27130, 'Romans 12:18', 'Romans', 12, 18, '&nbsp;ترڅو چې درنه کېدے شى نو د خپل طرف نه د هر چا سره صُلح ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27131, 'Romans 12:19', 'Romans', 12, 19, '&nbsp;اے زما عزيزانو، خپل بدل مۀ اخلئ بلکې خُدائ ته د بدل اخستو موقع ورکړئ، ځکه چې دا ليکلے شوى دى چې، ”مالِک خُدائ فرمائى چې بدل اخستل زما کار دے، بدل به زۀ اخلم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27132, 'Romans 12:20', 'Romans', 12, 20, '&nbsp;د دې په ځائ، ”کۀ ستا دشمنان اوږى وى نو هغوئ له روټۍ ورکړه او کۀ هغوئ تږى وى نو هغوئ ته اوبۀ ورکړه، ځکه چې ستا په داسې کولو به يې په سرونو اور بل شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27133, 'Romans 12:21', 'Romans', 12, 21, '&nbsp;بدۍ ته خپل ځان مۀ ښکته کوئ بلکې د نېکۍ په وسيله پرې بدۍ غالب شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27134, 'Romans 13:1', 'Romans', 13, 1, '&nbsp;هر څوک دې د سرکارى مشرانو تابعدار وى، ځکه چې ټول اختيار د خُدائ پاک د طرف نه دے او کوم سرکارى مشران چې موجود دى، هغه خُدائ پاک په خپله مقرر کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27135, 'Romans 13:2', 'Romans', 13, 2, '&nbsp;نو ځکه هر څوک چې د مشرانو تابعدارى نۀ کوى، هغه د خُدائ پاک د اِنتظام مخالفت کوى او څوک چې مخالفت کوى، هغوئ به سزا ومومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27136, 'Romans 13:3', 'Romans', 13, 3, '&nbsp;ځکه چې تابعدارو خلقو ته د مشرانو نه هيڅ يره نۀ وى خو نافرمانو ته وى. کۀ تاسو چرې د مشرانو په وړاندې بغېر د يرې اوسېدل غواړئ، نو تابعدارى کوئ او هغوئ به ستاسو تعريف کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27137, 'Romans 13:4', 'Romans', 13, 4, '&nbsp;ځکه چې هغوئ ستا د ښېګړې دپاره د خُدائ پاک خادِمان دى. خو کۀ چرې تاسو نافرمانى کوئ نو ويرېږئ، ځکه چې ستاسو سزا د هغوئ په لاس کښې ده او سزا به ضرور درکړى. هغوئ د خُدائ پاک خادِمان دى او د نافرمانو نه بدله اخلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27138, 'Romans 13:5', 'Romans', 13, 5, '&nbsp;نو ځکه دا ضرورى ده چې تاسو تابعدار اوسئ، نۀ صرف د سزا نه د بچ کېدو دپاره بلکې د دې دپاره چې ضمير مو په سکون کښې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27139, 'Romans 13:6', 'Romans', 13, 6, '&nbsp;هم په دې وجه تاسو خپل ټيکس ورکوئ ځکه چې دا اختيارمند مشران په خپلو مصروفياتو کښې د خُدائ پاک خادِمان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27140, 'Romans 13:7', 'Romans', 13, 7, '&nbsp;د ټولو حق پوره کوئ، چا ته چې ټيکس ورکول وى، هغوئ ته ټيکس ورکوئ، څوک چې د محصُول حقدار دى هغوئ ته محصُول ورکوئ، د چا چې احترام کول په کار دى، د هغوئ احترام کوئ، د چا چې عزت کول په کار دى، د هغوئ عزت کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27141, 'Romans 13:8', 'Romans', 13, 8, '&nbsp;هيڅ قسم قرض په ځان مۀ پرېږدئ. خو صرف يو کار چې هغه ستاسو دپاره ضرورى دے، هغه دا چې د يو بل سره مينه کوئ، نو په دې سره تاسو په شريعت پوره عمل وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27142, 'Romans 13:9', 'Romans', 13, 9, '&nbsp;ځکه چې دا حُکمونه دى چې، ”زنا مۀ کوئ، خُون مۀ کوئ، غلا مۀ کوئ، حرص مۀ کوئ،“ او د دې نه علاوه نور چې څۀ حُکمونه دى، د هغې ټولو خُلاصه په دې کښې ده چې، ”د خپل ګاونډى سره د خپل ځان په شان مينه ساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27143, 'Romans 13:10', 'Romans', 13, 10, '&nbsp;په چا کښې چې مينه وى هغه د خپل ګاونډى سره بد نۀ کوى، نو په دې سبب مينه کول د شريعت پوره کول دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27144, 'Romans 13:11', 'Romans', 13, 11, '&nbsp;د هر څۀ نه مخکښې دا خبره منل ضرورى ده، تاسو ته ښۀ پته ده چې وخت کم دے، د خوبه رابېدار شئ. ځکه چې زمونږ خلاصون رانزدې شوے دے د کوم وخت نه چې مو ايمان راوړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27145, 'Romans 13:12', 'Romans', 13, 12, '&nbsp;شپه په ختمېدو ده، ورځ په راتلو ده، نو راځئ چې مونږ د تيارې د کارونو نه لاس واخلو او د رڼا په وسله ځان سمبال کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27146, 'Romans 13:13', 'Romans', 13, 13, '&nbsp;راځئ چې د ورځې په رڼا کښې په عزت سره ژوند تېر کړُو، نۀ چې په ګډا او نشه بازۍ، نۀ په زناکارۍ، نۀ په مستۍ، او نۀ په شهوت پرستۍ، نۀ په جنګونو او حسد.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27147, 'Romans 13:14', 'Romans', 13, 14, '&nbsp;بلکې د دې په ځائ د مالِک عيسىٰ مسيح جامې په تن کړئ او د نفس د خواهشاتو دپاره تدبيرونه مۀ جوړَوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27148, 'Romans 14:1', 'Romans', 14, 1, '&nbsp;په ايمان کښې کمزورى خلق ځان سره شريک کړئ او په مسائيلو کښې ورسره بحث مباحثه مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
