(27194, 'Romans 15:24', 'Romans', 15, 24, '&nbsp;کله چې زۀ اسپانيه ته ځم نو په لاره به تاسو ته هم درځم ځکه چې زما دا اُميد دے چې په خپل دې سفر کښې به تاسو سره ملاقات کوم، او چې تاسو سره په څۀ موده تېرولو مې زړۀ موړ شى نو بيا به مې تاسو هغه طرف ته رُخصت کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27195, 'Romans 15:25', 'Romans', 15, 25, '&nbsp;خو اوس زۀ د مقدسينو د امداد دپاره يروشلم ته ځم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27196, 'Romans 15:26', 'Romans', 15, 26, '&nbsp;ځکه چې د مِکدونيه او د اخيه خلقو د زړۀ د اخلاصه د يروشلم د غريبو مقدسينو دپاره چنده کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27197, 'Romans 15:27', 'Romans', 15, 27, '&nbsp;هغوئ دا چنده په خوشحالۍ سره کړې ده ځکه چې هغوئ خپل ځان د دوئ قرضدار ګڼلو. ځکه چې غېر‌يهوديانو ته د زيرى روحانى برکتونه د يروشلم د ايماندارانو نه مِلاو شوى وُو نو هغوئ دا ضرورى وګڼله چې په مالى توګه د هغوئ مدد وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27198, 'Romans 15:28', 'Romans', 15, 28, '&nbsp;نو کله چې زۀ دا خِدمت پوره کړم او هغه پېسې هغوئ ته حواله کړم څۀ چې راغونډې شوې دى نو بيا به زۀ ستاسو په لار اسپانيه ته ځم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27199, 'Romans 15:29', 'Romans', 15, 29, '&nbsp;او ما ته پته ده چې کله زۀ تاسو ته درځم نو د عيسىٰ مسيح پوره برکت به دروړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27200, 'Romans 15:30', 'Romans', 15, 30, '&nbsp;او اے وروڼو او خوېندو، زۀ د عيسىٰ مسيح په وسيله څوک چې زمونږ مالِک دے او د روح د مينې په وسيله په تاسو زور راوړم چې زما دپاره د خُدائ پاک نه په دُعا غوښتو کښې ما سره يو ځائ شئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');